using System.Linq;

namespace Demo.Inventory;

public record Item(string Name, int Quantity, decimal Price);

public enum Status { Active, Retired }

public class Store
{
    private readonly List<Item> _items = new();

    public int Count => _items.Count;

    // Adds an item after validating it.
    public void Add(Item item)
    {
        if (item is null)
        {
            throw new ArgumentNullException(nameof(item));
        }
        _items.Add(item);
    }

    public decimal Total()
    {
        decimal sum = 0m;
        foreach (var item in _items)
        {
            sum += item.Price * item.Quantity;
        }
        return sum;
    }

    public string Describe(Item item) => item.Quantity switch
    {
        0 => "empty",
        < 10 => $"low: {item.Name}",
        _ => $"ok: {item.Name}",
    };

    public IEnumerable<string> Names() =>
        from i in _items where i.Quantity > 0 orderby i.Name select i.Name;
}

package inventory

import (
	"errors"
	"fmt"
	"strings"
)

// Item is a stock entry.
type Item struct {
	Name  string `json:"name"`
	Count int    `json:"count"`
}

type Store[K comparable, V any] struct {
	items map[K]V
}

const maxItems = 1_000

var ErrFull = errors.New("store is full")

func (s *Store[K, V]) Put(key K, value V) error {
	if len(s.items) >= maxItems {
		return ErrFull
	}
	s.items[key] = value
	return nil
}

func Summarize(items []Item) string {
	var b strings.Builder
	total := 0
	for i, it := range items {
		switch {
		case it.Count == 0:
			continue
		case it.Count > 100:
			fmt.Fprintf(&b, "%d:%s(bulk) ", i, it.Name)
		default:
			fmt.Fprintf(&b, "%d:%s ", i, it.Name)
		}
		total += it.Count
	}
	ch := make(chan int, 1)
	go func() { ch <- total }()
	defer close(ch)
	return b.String() + fmt.Sprint(<-ch)
}

