/** An item in stock. */
data class Item(val name: String, val count: Int = 0)

enum class Level { LOW, HIGH }

interface Repository<T> {
    fun add(item: T)
    fun all(): List<T>
}

class InMemoryRepository : Repository<Item> {
    private val items = mutableListOf<Item>()

    override fun add(item: Item) {
        require(item.count >= 0) { "negative count" }
        items.add(item)
    }

    override fun all(): List<Item> = items.toList()

    val total: Int
        get() = items.sumOf { it.count }
}

fun level(item: Item?): Level {
    val count = item?.count ?: 0
    return when {
        count > 100 -> Level.HIGH
        else -> Level.LOW
    }
}

fun main() {
    val repo = InMemoryRepository()
    for (i in 1..3) {
        repo.add(Item("item$i", i * 10))
    }
    // Print a summary line.
    println("total=${repo.total}, best=${max(repo.total, 1)}")
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ITEMS 16
#define SQUARE(x) ((x) * (x))

typedef struct {
    char name[32];
    int count;
} Item;

enum level { LEVEL_LOW, LEVEL_HIGH };

static Item items[MAX_ITEMS];
static size_t item_count = 0;

/* Adds an item; returns 0 on success. */
int add_item(const char *name, int count)
{
    if (item_count >= MAX_ITEMS) {
        return -1;
    }
    Item *it = &items[item_count++];
    strncpy(it->name, name, sizeof it->name - 1);
    it->count = count;
    return 0;
}

static enum level classify(const Item *it)
{
    switch (it->count) {
    case 0:
        return LEVEL_LOW;
    default:
        return it->count > 100 ? LEVEL_HIGH : LEVEL_LOW;
    }
}

int main(void)
{
    add_item("bolt", 120);
    add_item("nut", 4);
    long total = 0;
    for (size_t i = 0; i < item_count; i++) {
        total += SQUARE(items[i].count);
        printf("%s: %d\n", items[i].name, (int)classify(&items[i]));
    }
#ifdef VERBOSE
    printf("total=%ld\n", total);
#endif
    return total > 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}

