namespace inventory {

struct Item {
    std::string name;
    int count = 0;
};

template <typename T>
concept Countable = requires(T t) { t.count; };

class Store {
public:
    explicit Store(std::size_t limit) : limit_(limit) {}
    virtual ~Store() = default;

    bool add(Item item) {
        if (items_.size() >= limit_) {
            return false;
        }
        items_.push_back(std::move(item));
        return true;
    }

    template <Countable T>
    static int weight(const T& value) noexcept { return value.count * 2; }

    [[nodiscard]] int total() const {
        int sum = 0;
        for (const auto& [name, count] : index()) {
            sum += count;
        }
        return sum;
    }

private:
    std::map<std::string, int> index() const {
        std::map<std::string, int> out;
        for (const auto& it : items_) out[it.name] += it.count;
        return out;
    }

    std::size_t limit_;
    std::vector<Item> items_;
};

}  // namespace inventory

int main() {
    auto store = std::make_unique<inventory::Store>(8);
    store->add({"bolt", 3});
    auto doubled = [factor = 2](int x) { return x * factor; };
    std::cout << doubled(store->total()) << '\n';
    return 0;
}

use std::collections::HashMap;
use std::fmt;

/// An item in stock.
#[derive(Debug, Clone, PartialEq)]
pub struct Item {
    pub name: String,
    pub count: u32,
}

#[derive(Debug)]
pub enum Event {
    Added(Item),
    Removed { name: String },
}

pub trait Store {
    fn add(&mut self, item: Item) -> Result<(), String>;
    fn total(&self) -> u64;
}

#[derive(Default)]
pub struct MemoryStore<'a> {
    items: HashMap<String, Item>,
    label: &'a str,
}

impl<'a> Store for MemoryStore<'a> {
    fn add(&mut self, item: Item) -> Result<(), String> {
        if item.name.is_empty() {
            return Err(format!("empty name in {}", self.label));
        }
        self.items.insert(item.name.clone(), item);
        Ok(())
    }

    fn total(&self) -> u64 {
        self.items.values().map(|i| i.count as u64).sum()
    }
}

impl fmt::Display for Event {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Event::Added(item) if item.count > 100 => write!(f, "bulk {}", item.name),
            Event::Added(item) => write!(f, "added {}", item.name),
            Event::Removed { name } => write!(f, "removed {name}"),
        }
    }
}

macro_rules! square {
    ($x:expr) => {
        $x * $x
    };
}

fn main() {
    let mut store = MemoryStore { label: "main", ..Default::default() };
    for n in 1..=3 {
        let _ = store.add(Item { name: format!("item{n}"), count: square!(n) });
    }
    let Some(first) = store.items.values().next() else {
        return;
    };
    println!("{} {}", first.name, store.total());
}

