/// An item in stock.
class Item {
  final String name;
  final int count;

  const Item(this.name, [this.count = 0]);

  Item copyWith({int? count}) => Item(name, count ?? this.count);

  @override
  String toString() => 'Item($name, $count)';
}

enum Level { low, high }

mixin Logging {
  void log(String message) => print('[log] $message');
}

class Store with Logging {
  final _items = <String, Item>{};
  late final int limit;

  Store(this.limit);

  void add(Item item) {
    if (_items.length >= limit) {
      throw StateError('full');
    }
    _items[item.name] = item;
    log('added ${item.name}');
  }

  int get total => _items.values.fold(0, (sum, i) => sum + i.count);

  Level levelOf(String name) {
    final count = _items[name]?.count ?? 0;
    return count > 100 ? Level.high : Level.low;
  }
}

