CREATE OR ALTER PROCEDURE dbo.AddItem
    @Name NVARCHAR(100),
    @Quantity INT = 0
AS
BEGIN
    DECLARE @Existing INT;
    SELECT @Existing = Id FROM dbo.Items WHERE Name = @Name;
    IF @Existing IS NULL
    BEGIN
        INSERT INTO dbo.Items (Name, Quantity) VALUES (@Name, @Quantity);
    END
    ELSE
    BEGIN
        UPDATE dbo.Items SET Quantity = Quantity + @Quantity WHERE Id = @Existing;
    END
END
